class Solution {
public:
    ListNode* removeNthFromEnd(ListNode* head, int n) {
        int len = 0;
        for (ListNode* cur = head; cur; cur = cur->next) len++;
        ListNode dummy(0, head);
        ListNode* cur = &dummy;
        for (int i = 0; i < len - n; ++i) cur = cur->next;
        ListNode* toDelete = cur->next;
        cur->next = cur->next->next;
        delete toDelete;
        return dummy.next;
    }
};

